package com.alels.backend.telemetry.device.deviceworkspace.tab.configuration.datasource.controller;
import java.util.List;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import com.alels.backend.serverops.shared.security.JwtUserContext;import com.alels.backend.telemetry.device.deviceworkspace.tab.configuration.datasource.dto.DeviceWorkspaceDataSourceDtos.*;import com.alels.backend.telemetry.device.deviceworkspace.tab.configuration.datasource.service.DeviceWorkspaceDataSourceService;
@RestController @RequestMapping("/api/telemetry/devices/{deviceId}/workspace/configuration/data-source")
public class DeviceWorkspaceDataSourceController{private final DeviceWorkspaceDataSourceService service;public DeviceWorkspaceDataSourceController(DeviceWorkspaceDataSourceService service){this.service=service;}@GetMapping("/options")public List<SourceOption> options(Authentication a,@PathVariable Long deviceId){return service.options(user(a),deviceId);}@GetMapping("/profiles")public ProfileList profiles(Authentication a,@PathVariable Long deviceId){return service.profiles(user(a),deviceId);}@PostMapping("/profiles")public Profile save(Authentication a,@PathVariable Long deviceId,@RequestBody SaveProfileRequest r){return service.save(user(a),deviceId,r);}@PostMapping("/profiles/apply")public Profile apply(Authentication a,@PathVariable Long deviceId,@RequestBody ApplyProfileRequest r){return service.apply(user(a),deviceId,r);}@DeleteMapping("/profiles/{profileId}")@ResponseStatus(org.springframework.http.HttpStatus.NO_CONTENT)public void delete(Authentication a,@PathVariable Long deviceId,@PathVariable Long profileId){service.delete(user(a),deviceId,profileId);}private JwtUserContext user(Authentication a){return(JwtUserContext)a.getPrincipal();}}
